message.content:
{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the edge of the ruined city.",
      "visual_description": "A windswept ridge overlooks a shattered royal city at dusk; torn banners flap on broken spires. Mara unrolls a map across a stone while the tin fox sniffs the wind.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "Mara consults the oracle lamp for a warning.",
      "visual_description": "Close-up on Mara's ink-stained hands cupping the oil lamp; a single bright eye opens inside its flame, casting long shadows across her tired face.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The glass diver arrives by stepping out of a cracked window.",
      "visual_description": "A tall figure in a clear diving helmet emerges from a broken storefront pane as if surfacing from water, coat shimmering with reflected city lights.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "They approach the looming castle gates.",
      "visual_description": "Massive iron gates lean half off their hinges, carved with faded royal crests. The tin fox darts ahead, its key-wind tail clicking softly in the silence.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "An armored patrol marches past on the boulevard.",
      "visual_description": "From a low alley, Mara and the glass diver crouch behind rubble as plate-armored figures stomp by under torn banners. The lamp dims its eye to a pinhole.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "The tin fox scouts a side passage through a fallen archway.",
      "visual_description": "The small clockwork fox slips between rubble, blue glass eyes glowing as it surveys a moonlit courtyard strewn with abandoned market stalls.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Frightened faces peer from boarded windows above.",
      "visual_description": "Narrow shutters crack open along a leaning street; Mara raises her compass in a quiet sign of passage, her breath visible in cold air.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp warns of the cursed tower ahead.",
      "visual_description": "A black tower spirals against a green-tinged sky; the lamp's eye flares wide, projecting a warning rune across Mara's coat.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "They find the sleeping tax collector slumped in a tollhouse.",
      "visual_description": "A round official snores at a desk, head on a thick ledger pillow, stamped papers fluttering from his sleeves. The tin fox stares, head tilted.",
      "characters": ["sleeping_tax_collector", "tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "Mara questions the sleeping official, who only mumbles.",
      "visual_description": "Mara shakes the man's shoulder; he drools onto a permit stamped 'DENIED.' The glass diver watches from a mirror behind the desk, half submerged in its silver.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 11,
      "caption": "A rumor of winged shadows passes overhead.",
      "visual_description": "Vast scaled shadows ripple across cobblestones; Mara presses flat against a wall while the lamp shutters its eye to a single thread of light.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver dives through a stained glass window.",
      "visual_description": "Coat flaring with colored reflections, the glass diver plunges headfirst into a cathedral window without breaking it, leaving rippling glass behind.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Inside, the tin fox finds the locked magic door.",
      "visual_description": "A heavy door pulses with chalk-drawn sigils; the clockwork fox sits on its haunches, key-wind tail spinning slowly as it studies the patterns.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The oracle lamp reads the door's true name.",
      "visual_description": "Mara holds the lamp close; its flame stretches into letters that float onto the door, which clicks open in a soft puff of dust.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver"]guide
    },
    {
      "scene_number": 15,
      "caption": "They rouse the sleeping tax collector—their reluctant rescue target.",
      "visual_description": "Behind the door, the official is curled inside a velvet cell, still dozing. Mara groans, the glass diver lifts him by the collar, papers raining down.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols converge as alarm bells ring.",
      "visual_description": "Lanterns flare along the ramparts behind them; the tin fox races ahead, sparks trailing from its tail, leading the team down a collapsing staircase.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 17,
      "caption": "They sprint across the cracked bridge out of the city.",
      "visual_description": "A long stone bridge arches over a misty chasm; old royal banners snap in the wind as the team runs, the glass diver hauling the snoring official like a sack.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far side, Mara closes her map with a quiet smile.",
      "visual_description": "Dawn light spills over a green hill beyond the chasm. The tin fox curls at Mara's feet, the lamp's eye dims to a sleepy glow, and the official finally yawns awake.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector", "glass_diver"]
    }
  ]
}

